String[] tokens = tools.getParamValue("TemplateRFB").split("\\s");
if (tokens.length < 3) tokens = tools.getParamValue("TemplateRFB").split("!");
applicationName = tokens[0];
fileName = tokens[1];
fileType = tokens[2];

/* 
TASK-130045: This step is called only for Sizing wizard
This activity is modified to add step 4 as we don't want to write new activity
for Sizing wizard's excel file download. Reusing/modifying the original java step
of this activity will lead to lot of complexity hence created this new java step
*/

String xlFileName = tools.getParamValue("FSFileName");
PRFile xlFile = new PRFile(xlFileName);

java.io.OutputStream xlOS = null;
java.io.InputStream tempIS = null;
byte[] tempBytes = null;

try {
	ClipboardPage workPage = tools.findPage("pyWorkPage");

	tempBytes = new com.pega.pegarules.pub.util.Base64Util().decodeToByteArray(tools.findPage("TemplateFile").getString("pyFileSource"));
	tempIS = new java.io.ByteArrayInputStream(tempBytes);
	java.util.Map xlZipEntryMap = null;

	xlZipEntryMap = com.pegarules.generated.pega_appdefinition_excelintegration.DCOXLGenerateZipEntryMap(tempIS);

	xlOS = new PROutputStream(xlFile);
	com.pegarules.generated.pega_appdefinition_excelintegration.DCOzipEntryMapToStream(xlZipEntryMap, xlOS);
	if (tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "DownloadFile")) {
		pega_rules_default.downloadFile(xlFile.toString(), tools, true);
	}
}
catch (Exception e) {
	oLog.error("Error in parsing Excel file " + xlFileName, e);
	//throw new RuntimeException(e);
	tools.getStepPage().addMessage(e.toString());
}
finally {
	if (xlOS != null) try { xlOS.close(); } catch (Exception e) { }
	if (tempIS != null) try { tempIS.close(); } catch (Exception e) { }
}

String xlFileName = tools.getParamValue("FSFileName");
xlFileName = tools.findPage("pxProcess").getString("pxServiceExportPath") + xlFileName;
PRFile xlFile = new PRFile(xlFileName);

java.io.OutputStream xlOS = null;
java.io.InputStream tempIS = null;
byte[] tempBytes = null;
boolean projectSizingPresent = false;
String strWorkObjectRef = "";
ClipboardPage objRefPage = null;
java.util.ArrayList sizingList = new java.util.ArrayList();
try {
	ClipboardPage workPage = tools.findPage("pyWorkPage");
	String hasAttachments = "false";
	//checking if not running on any wizard .i.e from Spec/Req LP
	if( workPage!= null){
		hasAttachments=workPage.getString("pyHasAttachments");
	}
	boolean sizingAttachmentPresent = false;
	if((tools.getParamValue("TemplateRFB").indexOf("ProjectSizing") > 0) && ("true".equalsIgnoreCase(hasAttachments))){  
		// Added by Rakesh (Task-4114): If we are dealing with project sizing sheet, only then check for the attachments, else directly get the excel template for requirements/usecases.

		ClipboardProperty attachCat = workPage.getProperty("pyAttachmentCategories");
		Iterator attachIter = attachCat.iterator();
		while(attachIter.hasNext()){
			ClipboardProperty attachProp = (ClipboardProperty)attachIter.next();
			if("ProjectSizing".equals(attachProp.getStringValue())) {
				projectSizingPresent = true;
				break;
			}
		}

		if((projectSizingPresent) && (tools.findPage("SizingAttachmentList").getProperty("pxResults").size()>0)){
			sizingAttachmentPresent = true;
			// Added by Rakesh (Task-4114): If project sizing sheet is already present, use it otherwise use the blank template.
			// The SizingAttachmentList will contain the list of existing sizing sheets in descending order of pxCreateDateTime.
			// So we pick the latest sizing sheet.
			ClipboardPage latestSizingSheet = tools.findPage("SizingAttachmentList").getProperty("pxResults").getPageValue(1);
			try {
				strWorkObjectRef = latestSizingSheet.getString("pxLinkedRefTo");
				objRefPage = tools.createPage("Data-WorkAttach-File","ExistingSizingAttachment") ;
				// try to open the file attachment record
				objRefPage.replace(tools.getDatabase().open(strWorkObjectRef, true));
				if (objRefPage == null) {
					tools.getThread().getThreadPage().putString("pyXMLStream", "No such record: " + strWorkObjectRef);
					pega.terminateActivity();
				}

				fileName = objRefPage.getString("pxAttachName");
				if(fileName.length() == 0) {
					fileName = xlFileName;
				}
				if(fileName.contains("\\")) {
					fileName = fileName.substring( fileName.lastIndexOf('\\') + 1 );
				}
				if(fileName.contains("/")) {
					fileName = fileName.substring( fileName.lastIndexOf('/') + 1);
				}
				if(fileName.contains(java.io.File.separator)) {
					fileName = fileName.substring( fileName.lastIndexOf(java.io.File.separatorChar) + 1);
				}
				if(fileName.contains(".")) {
					fileType = fileName.substring(fileName.lastIndexOf('.') + 1);
					fileName = fileName.substring(0, fileName.lastIndexOf('.'));
				}
				else {
					fileType = "xlsm";
				}
				xlFile = new PRFile(fileName + '.' + fileType);
			}
			catch (DatabaseException dbEx) {
				oLog.error("Error opening File Attachment", dbEx);
				tools.getThread().getThreadPage().putString("pyXMLStream", "Can't open record: " + strWorkObjectRef);
				pega.terminateActivity();
			}
		        //Bug-63382	String strFileData = objRefPage.getString("pyAttachStream");
                        String strFileData = pega_processengine_workutilities.pxGetFileAttachmentContent(objRefPage);
			tempBytes = new com.pega.pegarules.pub.util.Base64Util().decodeToByteArray(strFileData);
		}
		else{
			tempBytes = new com.pega.pegarules.pub.util.Base64Util().decodeToByteArray(tools.findPage("TemplateFile").getString("pyFileSource"));
		}
	}
	else{
		tempBytes = new com.pega.pegarules.pub.util.Base64Util().decodeToByteArray(tools.findPage("TemplateFile").getString("pyFileSource"));
	}

	tempIS = new java.io.ByteArrayInputStream(tempBytes);
	java.util.Map xlZipEntryMap = null;
	if(sizingAttachmentPresent){
		xlZipEntryMap  = com.pegarules.generated.pega_appdefinition_excelintegration.DCOXLGenerateZipEntryMap2(tempIS,tools);
	}
	else{
		xlZipEntryMap = com.pegarules.generated.pega_appdefinition_excelintegration.DCOXLGenerateZipEntryMap(tempIS);
	}
	xlOS = new PROutputStream(xlFile);
	com.pegarules.generated.pega_appdefinition_excelintegration.DCOzipEntryMapToStream(xlZipEntryMap, xlOS);
	if (tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "DownloadFile")) {
		pega_rules_default.downloadFile(xlFile.toString(), tools, true);
	}
}
catch (Exception e) {
	oLog.error("Error in parsing Excel file " + xlFileName, e);
	//throw new RuntimeException(e);
	tools.getStepPage().addMessage(e.toString());
}
finally {
	if (xlOS != null) try { xlOS.close(); } catch (Exception e) { }
	if (tempIS != null) try { tempIS.close(); } catch (Exception e) { }
}
